    sampling_ratio    = cfg.MODEL.ROI_KEYPOINT_HEAD.POOLER_SAMPLING_RATIO
    pooler_type       = cfg.MODEL.ROI_KEYPOINT_HEAD.POOLER_TYPE
    # fmt: on

