    self.use_heatmap_max_keypoint = use_heatmap_max_keypoint

def forward(self, x):
    x = self.patch_embed(x)
    if self.pos_embed is not None:
        x = x + get_abs_pos(
            self.pos_embed, self.pretrain_use_cls_token, (x.shape[1], x.shape[2])
        )

    for blk in self.blocks:
        x = blk(x)

    outputs = {self._out_features[0]: x.permute(0, 3, 1, 2)}
    return outputs

def _assert_strides_are_log2_contiguous(strides):
    """
    Assert that each stride is 2x times its preceding stride, i.e. "contiguous in log2".
    """
    for i, stride in enumerate(strides[1:], 1):
        assert stride == 2 * strides[i - 1], "Strides {} {} are not log2 contiguous".format(
            stride, strides[i - 1]
        )

def padding_constraints(self):
    return {
        "size_divisiblity": self._size_divisibility,
        "square_size": self._square_pad,
    }

def forward(self, x):
    """
    Args:
        x: Tensor of shape (N,C,H,W). H, W must be a multiple of ``self.size_divisibility``.

    Returns:
        dict[str->Tensor]: names and the corresponding features
    """
    assert x.dim() == 4, f"ResNet takes an input of shape (N, C, H, W). Got {x.shape} instead!"
    outputs = {}
    x = self.stem(x)
    if "stem" in self._out_features:
        outputs["stem"] = x
    for name, stage in zip(self.stage_names, self.stages):
        x = stage(x)
        if name in self._out_features:
            outputs[name] = x
    if self.num_classes is not None:
        x = self.avgpool(x)
        x = torch.flatten(x, 1)
        x = self.linear(x)
        if "linear" in self._out_features:
            outputs["linear"] = x
    return outputs

def forward(self, x):
    # torchscript does not support SyncBatchNorm yet
    # https://github.com/pytorch/pytorch/issues/40507
    # and we skip these codes in torchscript since:
    # 1. currently we only support torchscript in evaluation mode
    # 2. features needed by exporting module to torchscript are added in PyTorch 1.6 or
    # later version, `Conv2d` in these PyTorch versions has already supported empty inputs.
    if not torch.jit.is_scripting():
        if x.numel() == 0 and self.training:
            # https://github.com/pytorch/pytorch/issues/12013
            assert not isinstance(
                self.norm, torch.nn.SyncBatchNorm
            ), "SyncBatchNorm does not support empty inputs!"

    x = F.conv2d(
        x, self.weight, self.bias, self.stride, self.padding, self.dilation, self.groups
    )
    if self.norm is not None:
        x = self.norm(x)
    if self.activation is not None:
        x = self.activation(x)
    return x

def forward(self, x, offset):
    if x.numel() == 0:
        # When input is empty, we want to return a empty tensor with "correct" shape,
        # So that the following operations will not panic
        # if they check for the shape of the tensor.
        # This computes the height and width of the output tensor
        output_shape = [
            (i + 2 * p - (di * (k - 1) + 1)) // s + 1
            for i, p, di, k, s in zip(
                x.shape[-2:], self.padding, self.dilation, self.kernel_size, self.stride
            )
        ]
        output_shape = [x.shape[0], self.weight.shape[0]] + output_shape
        return _NewEmptyTensorOp.apply(x, output_shape)

    x = deform_conv(
        x,
        offset,
        self.weight,
        self.stride,
        self.padding,
        self.dilation,
        self.groups,
        self.deformable_groups,
    )
    if self.norm is not None:
        x = self.norm(x)
    if self.activation is not None:
        x = self.activation(x)
    return x

def forward(self, x, offset, mask):
    if x.numel() == 0:
        output_shape = [
            (i + 2 * p - (di * (k - 1) + 1)) // s + 1
            for i, p, di, k, s in zip(
                x.shape[-2:], self.padding, self.dilation, self.kernel_size, self.stride
            )
        ]
        output_shape = [x.shape[0], self.weight.shape[0]] + output_shape
        return _NewEmptyTensorOp.apply(x, output_shape)

    x = modulated_deform_conv(
        x,
        offset,
        mask,
        self.weight,
        self.bias,
        self.stride,
        self.padding,
        self.dilation,
        self.groups,
        self.deformable_groups,
    )
    if self.norm is not None:
        x = self.norm(x)
    if self.activation is not None:
        x = self.activation(x)
    return x

def forward(self, x):
    x_p = self.bn(self.proj(x)) if self.proj else x
    return self.af(x_p + self.f(x))

def forward(self, x):
    x_p = self.bn(self.proj(x)) if self.proj else x
    return self.af(x_p + self.f(x))

def cross_entropy(input, target, *, reduction="mean", **kwargs):
    """
    Same as `torch.nn.functional.cross_entropy`, but returns 0 (instead of nan)
    for empty inputs.
    """
    if target.numel() == 0 and reduction == "mean":
        return input.sum() * 0.0  # connect the gradient
    return F.cross_entropy(input, target, reduction=reduction, **kwargs)

def apply_image(self, img):
    img = Image.fromarray(img)
    return np.asarray(super().apply_image(img))

def conv2d(w_in, w_out, k, *, stride=1, groups=1, bias=False):
    """Helper for building a conv2d layer."""
    assert k % 2 == 1, "Only odd size kernels supported to avoid padding issues."
    s, p, g, b = stride, (k - 1) // 2, groups, bias
    return nn.Conv2d(w_in, w_out, k, stride=s, padding=p, groups=g, bias=b)

def pool2d(k, *, stride=1):
    """Helper for building a pool2d layer."""
    assert k % 2 == 1, "Only odd size kernels supported to avoid padding issues."
    return nn.MaxPool2d(k, stride=stride, padding=(k - 1) // 2)

def gap2d():
    """Helper for building a global average pooling layer."""
    return nn.AdaptiveAvgPool2d((1, 1))

def init_weights(m):
    """Performs ResNet-style weight initialization."""
    if isinstance(m, nn.Conv2d):
        # Note that there is no bias due to BN
        fan_out = m.kernel_size[0] * m.kernel_size[1] * m.out_channels
        m.weight.data.normal_(mean=0.0, std=np.sqrt(2.0 / fan_out))
    elif isinstance(m, nn.BatchNorm2d):
        m.weight.data.fill_(1.0)
        m.bias.data.zero_()
    elif isinstance(m, nn.Linear):
        m.weight.data.normal_(mean=0.0, std=0.01)
        m.bias.data.zero_()

def to(self, device: torch.device):
    # Boxes are assumed float32 and does not support to(dtype)
    return RotatedBoxes(self.tensor.to(device=device))

def to(self, device: torch.device):
    # Boxes are assumed float32 and does not support to(dtype)
    return Boxes(self.tensor.to(device=device))

def shapes_to_tensor(x: List[int], device: Optional[torch.device] = None) -> torch.Tensor:
    """
    Turn a list of integer scalars or integer Tensor scalars into a vector,
    in a way that's both traceable and scriptable.

    In tracing, `x` should be a list of scalar Tensor, so the output can trace to the inputs.
    In scripting or eager, `x` should be a list of int.
    """
    if torch.jit.is_scripting():
        return torch.as_tensor(x, device=device)
    if torch.jit.is_tracing():
        assert all(
            [isinstance(t, torch.Tensor) for t in x]
        ), "Shape should be tensor during tracing!"
        # as_tensor should not be used in tracing because it records a constant
        ret = torch.stack(x)
        if ret.device != device:  # avoid recording a hard-coded device if not necessary
            ret = ret.to(device=device)
        return ret
    return torch.as_tensor(x, device=device)

def backward(ctx, grad):
    shape = ctx.shape
    return _NewEmptyTensorOp.apply(grad, shape), None

def forward_training(self, images, features, predictions, gt_instances):
    # Transpose the Hi*Wi*A dimension to the middle:
    pred_logits, pred_anchor_deltas, pred_centerness = self._transpose_dense_predictions(
        predictions, [self.num_classes, 4, 1]
    )
    anchors = self.anchor_generator(features)
    gt_labels, gt_boxes = self.label_anchors(anchors, gt_instances)
    return self.losses(
        anchors, pred_logits, gt_labels, pred_anchor_deltas, gt_boxes, pred_centerness
    )

