def _shard_iterator_dataloader_worker(iterable):
    # Shard the iterable if we're currently inside pytorch dataloader worker.
    worker_info = data.get_worker_info()
    if worker_info is None or worker_info.num_workers == 1:
        # do nothing
        yield from iterable
    else:
        yield from itertools.islice(iterable, worker_info.id, None, worker_info.num_workers)

def __iter__(self):
    if not self.shard_sampler:
        sampler = self.sampler
    else:
        # With map-style dataset, `DataLoader(dataset, sampler)` runs the
        # sampler in main process only. But `DataLoader(ToIterableDataset(dataset, sampler))`
        # will run sampler in every of the N worker. So we should only keep 1/N of the ids on
        # each worker. The assumption is that sampler is cheap to iterate so it's fine to
        # discard ids in workers.
        sampler = _shard_iterator_dataloader_worker(self.sampler)
    for idx in sampler:
        yield self.dataset[idx]

def __getitem__(self, idx):
    retry_count = 0
    cur_idx = int(idx)

    while True:
        data = self._map_func(self._dataset[cur_idx])
        if data is not None:
            self._fallback_candidates.add(cur_idx)
            return data

        # _map_func fails for this idx, use a random new index from the pool
        retry_count += 1
        self._fallback_candidates.discard(cur_idx)
        cur_idx = self._rng.sample(self._fallback_candidates, k=1)[0]

        if retry_count >= 3:
            logger = logging.getLogger(__name__)
            logger.warning(
                "Failed to apply `_map_func` for idx: {}, retry count: {}".format(
                    idx, retry_count
                )
            )

def __len__(self):
    if self._serialize:
        return len(self._addr)
    else:
        return len(self._lst)

def _infinite_indices(self):
    g = torch.Generator()
    g.manual_seed(self._seed)  # self._seed equals seed_shuffle from __init__()
    while True:
        if self._shuffle:
            # generate a random permutation to shuffle self._indexes_subset
            randperm = torch.randperm(self._size_subset, generator=g)
            yield from self._indexes_subset[randperm].tolist()
        else:
            yield from self._indexes_subset.tolist()

def forward(self, x):
    ret = self[self._pos](x)
    self._pos = (self._pos + 1) % len(self)

    if self._affine:
        w = self.weight.reshape(1, -1, 1, 1)
        b = self.bias.reshape(1, -1, 1, 1)
        return ret * w + b
    else:
        return ret

def has_holes(self):
    if self._has_holes is None:
        if self._mask is not None:
            self._polygons, self._has_holes = self.mask_to_polygons(self._mask)
        else:
            self._has_holes = False  # if original format is polygon, does not have holes
    return self._has_holes

def _serialize(data):
    buffer = pickle.dumps(data, protocol=-1)
    return np.frombuffer(buffer, dtype=np.uint8)

def __getitem__(self, idx):
    if self._serialize:
        start_addr = 0 if idx == 0 else self._addr[idx - 1].item()
        end_addr = self._addr[idx].item()
        bytes = memoryview(self._lst[start_addr:end_addr])
        return pickle.loads(bytes)
    elif self._copy:
        return copy.deepcopy(self._lst[idx])
    else:
        return self._lst[idx]

def _get_local_indices(total_size, world_size, rank):
    shard_size = total_size // world_size
    left = total_size % world_size
    shard_sizes = [shard_size + int(r < left) for r in range(world_size)]

    begin = sum(shard_sizes[:rank])
    end = min(sum(shard_sizes[: rank + 1]), total_size)
    return range(begin, end)

