def flatten_results_dict(results):
    """
    Expand a hierarchical dict of scalars into a flat dict of scalars.
    If results[k1][k2][k3] = v, the returned dict will have the entry
    {"k1/k2/k3": v}.

    Args:
        results (dict):
    """
    r = {}
    for k, v in results.items():
        if isinstance(v, Mapping):
            v = flatten_results_dict(v)
            for kk, vv in v.items():
                r[k + "/" + kk] = vv
        else:
            r[k] = v
    return r

def _do_eval(self):
    results = self._func()

    if results:
        assert isinstance(
            results, dict
        ), "Eval function must return a dict. Got {} instead.".format(results)

        flattened_results = flatten_results_dict(results)
        for k, v in flattened_results.items():
            try:
                v = float(v)
            except Exception as e:
                raise ValueError(
                    "[EvalHook] eval_function should return a nested dict of float. "
                    "Got '{}: {}' instead.".format(k, v)
                ) from e
        self.trainer.storage.put_scalars(**flattened_results, smoothing_hint=False)

    # Evaluation may take different time among workers.
    # A barrier make them start the next iteration together.
    comm.synchronize()

def after_step(self):
    next_iter = self.trainer.iter + 1
    if self._period > 0 and next_iter % self._period == 0:
        # do the last eval in after_train
        if next_iter != self.trainer.max_iter:
            self._do_eval()

def cat(tensors: List[torch.Tensor], dim: int = 0):
    """
    Efficient version of torch.cat that avoids a copy if there is only a single element in a list
    """
    assert isinstance(tensors, (list, tuple))
    if len(tensors) == 1:
        return tensors[0]
    return torch.cat(tensors, dim)

def nonzero_tuple(x):
    """
    A 'as_tuple=True' version of torch.nonzero to support torchscript.
    because of https://github.com/pytorch/pytorch/issues/38718
    """
    if torch.jit.is_scripting():
        if x.dim() == 0:
            return x.unsqueeze(0).nonzero().unbind(1)
        return x.nonzero().unbind(1)
    else:
        return x.nonzero(as_tuple=True)

def state_dict(self):
    """
    Hooks are stateless by default, but can be made checkpointable by
    implementing `state_dict` and `load_state_dict`.
    """
    return {}

def state_dict(self):
    ret = {"iteration": self.iter}
    hooks_state = {}
    for h in self._hooks:
        sd = h.state_dict()
        if sd:
            name = type(h).__qualname__
            if name in hooks_state:
                # TODO handle repetitive stateful hooks
                continue
            hooks_state[name] = sd
    if hooks_state:
        ret["hooks"] = hooks_state
    return ret

def load_state_dict(self, state_dict):
    logger = logging.getLogger(__name__)
    self.iter = state_dict["iteration"]
    for key, value in state_dict.get("hooks", {}).items():
        for h in self._hooks:
            try:
                name = type(h).__qualname__
            except AttributeError:
                continue
            if name == key:
                h.load_state_dict(value)
                break
        else:
            logger.warning(f"Cannot find the hook '{key}', its state_dict is ignored.")

def load_state_dict(self, state_dict):
    super().load_state_dict(state_dict)
    self.optimizer.load_state_dict(state_dict["optimizer"])

def load_state_dict(self, state_dict):
    super().load_state_dict(state_dict)
    self.grad_scaler.load_state_dict(state_dict["grad_scaler"])

def load_state_dict(self, state_dict):
    if isinstance(self.scheduler, torch.optim.lr_scheduler._LRScheduler):
        logger = logging.getLogger(__name__)
        logger.info("Loading scheduler from state_dict ...")
        self.scheduler.load_state_dict(state_dict)

def load_state_dict(self, state_dict):
    super().load_state_dict(state_dict)
    self._trainer.load_state_dict(state_dict["_trainer"])

def _output_size(input, weight, padding, dilation, stride):
    channels = weight.size(0)
    output_size = (input.size(0), channels)
    for d in range(input.dim() - 2):
        in_size = input.size(d + 2)
        pad = padding[d]
        kernel = dilation[d] * (weight.size(d + 2) - 1) + 1
        stride_ = stride[d]
        output_size += ((in_size + (2 * pad) - kernel) // stride_ + 1,)
    if not all(map(lambda s: s > 0, output_size)):
        raise ValueError(
            "convolution input is too small (output would be {})".format(
                "x".join(map(str, output_size))
            )
        )
    return output_size

def find_spec(self, name, path, target=None):
    if not name.startswith("detectron2.projects."):
        return
    project_name = name.split(".")[-1]
    project_dir = _PROJECTS.get(project_name)
    if not project_dir:
        return
    target_file = _PROJECT_ROOT / f"{project_dir}/{project_name}/__init__.py"
    if not target_file.is_file():
        return
    return importlib.util.spec_from_file_location(name, target_file)

