def guess_version(cfg: CN, filename: str) -> int:
    """
    Guess the version of a partial config where the VERSION field is not specified.
    Returns the version, or the latest if cannot make a guess.

    This makes it easier for users to migrate.
    """
    logger = logging.getLogger(__name__)

    def _has(name: str) -> bool:
        cur = cfg
        for n in name.split("."):
            if n not in cur:
                return False
            cur = cur[n]
        return True

    # Most users' partial configs have "MODEL.WEIGHT", so guess on it
    ret = None
    if _has("MODEL.WEIGHT") or _has("TEST.AUG_ON"):
        ret = 1

    if ret is not None:
        logger.warning("Config '{}' has no VERSION. Assuming it to be v{}.".format(filename, ret))
    else:
        ret = _C.VERSION
        logger.warning(
            "Config '{}' has no VERSION. Assuming it to be compatible with latest v{}.".format(
                filename, ret
            )
        )
    return ret

def _has(name: str) -> bool:
    cur = cfg
    for n in name.split("."):
        if n not in cur:
            return False
        cur = cur[n]
    return True

def configurable(init_func=None, *, from_config=None):
    """
    Decorate a function or a class's __init__ method so that it can be called
    with a :class:`CfgNode` object using a :func:`from_config` function that translates
    :class:`CfgNode` to arguments.

    Examples:
    ::
        # Usage 1: Decorator on __init__:
        class A:
            @configurable
            def __init__(self, a, b=2, c=3):
                pass

            @classmethod
            def from_config(cls, cfg):   # 'cfg' must be the first argument
                # Returns kwargs to be passed to __init__
                return {"a": cfg.A, "b": cfg.B}

        a1 = A(a=1, b=2)  # regular construction
        a2 = A(cfg)       # construct with a cfg
        a3 = A(cfg, b=3, c=4)  # construct with extra overwrite

        # Usage 2: Decorator on any function. Needs an extra from_config argument:
        @configurable(from_config=lambda cfg: {"a: cfg.A, "b": cfg.B})
        def a_func(a, b=2, c=3):
            pass

        a1 = a_func(a=1, b=2)  # regular call
        a2 = a_func(cfg)       # call with a cfg
        a3 = a_func(cfg, b=3, c=4)  # call with extra overwrite

    Args:
        init_func (callable): a class's ``__init__`` method in usage 1. The
            class must have a ``from_config`` classmethod which takes `cfg` as
            the first argument.
        from_config (callable): the from_config function in usage 2. It must take `cfg`
            as its first argument.
    """

    if init_func is not None:
        assert (
            inspect.isfunction(init_func)
            and from_config is None
            and init_func.__name__ == "__init__"
        ), "Incorrect use of @configurable. Check API documentation for examples."

        @functools.wraps(init_func)
        def wrapped(self, *args, **kwargs):
            try:
                from_config_func = type(self).from_config
            except AttributeError as e:
                raise AttributeError(
                    "Class with @configurable must have a 'from_config' classmethod."
                ) from e
            if not inspect.ismethod(from_config_func):
                raise TypeError("Class with @configurable must have a 'from_config' classmethod.")

            if _called_with_cfg(*args, **kwargs):
                explicit_args = _get_args_from_config(from_config_func, *args, **kwargs)
                init_func(self, **explicit_args)
            else:
                init_func(self, *args, **kwargs)

        return wrapped

    else:
        if from_config is None:
            return configurable  # @configurable() is made equivalent to @configurable
        assert inspect.isfunction(
            from_config
        ), "from_config argument of configurable must be a function!"

        def wrapper(orig_func):
            @functools.wraps(orig_func)
            def wrapped(*args, **kwargs):
                if _called_with_cfg(*args, **kwargs):
                    explicit_args = _get_args_from_config(from_config, *args, **kwargs)
                    return orig_func(**explicit_args)
                else:
                    return orig_func(*args, **kwargs)

            wrapped.from_config = from_config
            return wrapped

        return wrapper

def _get_args_from_config(from_config_func, *args, **kwargs):
    """
    Use `from_config` to obtain explicit arguments.

    Returns:
        dict: arguments to be used for cls.__init__
    """
    signature = inspect.signature(from_config_func)
    if list(signature.parameters.keys())[0] != "cfg":
        if inspect.isfunction(from_config_func):
            name = from_config_func.__name__
        else:
            name = f"{from_config_func.__self__}.from_config"
        raise TypeError(f"{name} must take 'cfg' as the first argument!")
    support_var_arg = any(
        param.kind in [param.VAR_POSITIONAL, param.VAR_KEYWORD]
        for param in signature.parameters.values()
    )
    if support_var_arg:  # forward all arguments to from_config, if from_config accepts them
        ret = from_config_func(*args, **kwargs)
    else:
        # forward supported arguments to from_config
        supported_arg_names = set(signature.parameters.keys())
        extra_kwargs = {}
        for name in list(kwargs.keys()):
            if name not in supported_arg_names:
                extra_kwargs[name] = kwargs.pop(name)
        ret = from_config_func(*args, **kwargs)
        # forward the other arguments to __init__
        ret.update(extra_kwargs)
    return ret

def wrapped(self, *args, **kwargs):
    try:
        from_config_func = type(self).from_config
    except AttributeError as e:
        raise AttributeError(
            "Class with @configurable must have a 'from_config' classmethod."
        ) from e
    if not inspect.ismethod(from_config_func):
        raise TypeError("Class with @configurable must have a 'from_config' classmethod.")

    if _called_with_cfg(*args, **kwargs):
        explicit_args = _get_args_from_config(from_config_func, *args, **kwargs)
        init_func(self, **explicit_args)
    else:
        init_func(self, *args, **kwargs)

def wrapper(orig_func):
    @functools.wraps(orig_func)
    def wrapped(*args, **kwargs):
        if _called_with_cfg(*args, **kwargs):
            explicit_args = _get_args_from_config(from_config, *args, **kwargs)
            return orig_func(**explicit_args)
        else:
            return orig_func(*args, **kwargs)

    wrapped.from_config = from_config
    return wrapped

def wrapped(*args, **kwargs):
    if _called_with_cfg(*args, **kwargs):
        explicit_args = _get_args_from_config(from_config, *args, **kwargs)
        return orig_func(**explicit_args)
    else:
        return orig_func(*args, **kwargs)

def _rename(cfg: CN, old: str, new: str) -> None:
    old_keys = old.split(".")
    new_keys = new.split(".")

    def _set(key_seq: List[str], val: str) -> None:
        cur = cfg
        for k in key_seq[:-1]:
            if k not in cur:
                cur[k] = CN()
            cur = cur[k]
        cur[key_seq[-1]] = val

    def _get(key_seq: List[str]) -> CN:
        cur = cfg
        for k in key_seq:
            cur = cur[k]
        return cur

    def _del(key_seq: List[str]) -> None:
        cur = cfg
        for k in key_seq[:-1]:
            cur = cur[k]
        del cur[key_seq[-1]]
        if len(cur) == 0 and len(key_seq) > 1:
            _del(key_seq[:-1])

    _set(new_keys, _get(old_keys))
    _del(old_keys)

def downgrade(cls, cfg: CN) -> None:
    for old, new in cls.RENAME[::-1]:
        _rename(cfg, new, old)

def _set(key_seq: List[str], val: str) -> None:
    cur = cfg
    for k in key_seq[:-1]:
        if k not in cur:
            cur[k] = CN()
        cur = cur[k]
    cur[key_seq[-1]] = val

def _get(key_seq: List[str]) -> CN:
    cur = cfg
    for k in key_seq:
        cur = cur[k]
    return cur

def _del(key_seq: List[str]) -> None:
    cur = cfg
    for k in key_seq[:-1]:
        cur = cur[k]
    del cur[key_seq[-1]]
    if len(cur) == 0 and len(key_seq) > 1:
        _del(key_seq[:-1])

def _visit_dict_config(cfg, func):
    """
    Apply func recursively to all DictConfig in cfg.
    """
    if isinstance(cfg, DictConfig):
        func(cfg)
        for v in cfg.values():
            _visit_dict_config(v, func)
    elif isinstance(cfg, ListConfig):
        for v in cfg:
            _visit_dict_config(v, func)

def save(cfg, filename: str):
    """
    Save a config object to a yaml file.
    Note that when the config dictionary contains complex objects (e.g. lambda),
    it can't be saved to yaml. In that case we will print an error and
    attempt to save to a pkl file instead.

    Args:
        cfg: an omegaconf config object
        filename: yaml file name to save the config file
    """
    logger = logging.getLogger(__name__)
    try:
        cfg = deepcopy(cfg)
    except Exception:
        pass
    else:
        # if it's deep-copyable, then...
        def _replace_type_by_name(x):
            if "_target_" in x and callable(x._target_):
                try:
                    x._target_ = _convert_target_to_string(x._target_)
                except AttributeError:
                    pass

        # not necessary, but makes yaml looks nicer
        _visit_dict_config(cfg, _replace_type_by_name)

    save_pkl = False
    try:
        dict = OmegaConf.to_container(cfg, resolve=False)
        dumped = yaml.dump(dict, default_flow_style=None, allow_unicode=True, width=9999)
        with PathManager.open(filename, "w") as f:
            f.write(dumped)

        try:
            _ = yaml.unsafe_load(dumped)  # test that it is loadable
        except Exception:
            logger.warning(
                "The config contains objects that cannot serialize to a valid yaml. "
                f"{filename} is human-readable but cannot be loaded."
            )
            save_pkl = True
    except Exception:
        logger.exception("Unable to serialize the config to yaml. Error:")
        save_pkl = True

    if save_pkl:
        new_filename = filename + ".pkl"
        try:
            # retry by pickle
            with PathManager.open(new_filename, "wb") as f:
                cloudpickle.dump(cfg, f)
            logger.warning(f"Config is saved using cloudpickle at {new_filename}.")
        except Exception:
            pass

def _replace_type_by_name(x):
    if "_target_" in x and callable(x._target_):
        try:
            x._target_ = _convert_target_to_string(x._target_)
        except AttributeError:
            pass

def _validate_py_syntax(filename):
    # see also https://github.com/open-mmlab/mmcv/blob/master/mmcv/utils/config.py
    with PathManager.open(filename, "r") as f:
        content = f.read()
    try:
        ast.parse(content)
    except SyntaxError as e:
        raise SyntaxError(f"Config file {filename} has syntax error!") from e

def _cast_to_config(obj):
    # if given a dict, return DictConfig instead
    if isinstance(obj, dict):
        return DictConfig(obj, flags={"allow_objects": True})
    return obj

def _random_package_name(filename):
    # generate a random package name when loading config files
    return _CFG_PACKAGE_NAME + str(uuid.uuid4())[:4] + "." + os.path.basename(filename)

def load(filename: str, keys: Union[None, str, Tuple[str, ...]] = None):
    """
    Load a config file.

    Args:
        filename: absolute path or relative path w.r.t. the current working directory
        keys: keys to load and return. If not given, return all keys
            (whose values are config objects) in a dict.
    """
    has_keys = keys is not None
    filename = filename.replace("/./", "/")  # redundant
    if os.path.splitext(filename)[1] not in [".py", ".yaml", ".yml"]:
        raise ValueError(f"Config file {filename} has to be a python or yaml file.")
    if filename.endswith(".py"):
        _validate_py_syntax(filename)

        with _patch_import():
            # Record the filename
            module_namespace = {
                "__file__": filename,
                "__package__": _random_package_name(filename),
            }
            with PathManager.open(filename) as f:
                content = f.read()
            # Compile first with filename to:
            # 1. make filename appears in stacktrace
            # 2. make load_rel able to find its parent's (possibly remote) location
            exec(compile(content, filename, "exec"), module_namespace)

        ret = module_namespace
    else:
        with PathManager.open(filename) as f:
            obj = yaml.unsafe_load(f)
        ret = OmegaConf.create(obj, flags={"allow_objects": True})

    if has_keys:
        if isinstance(keys, str):
            return _cast_to_config(ret[keys])
        else:
            return tuple(_cast_to_config(ret[a]) for a in keys)
    else:
        if filename.endswith(".py"):
            # when not specified, only load those that are config objects
            ret = DictConfig(
                {
                    name: _cast_to_config(value)
                    for name, value in ret.items()
                    if isinstance(value, (DictConfig, ListConfig, dict))
                    and not name.startswith("_")
                },
                flags={"allow_objects": True},
            )
        return ret

def find_relative_file(original_file, relative_import_path, level):
    cur_file = os.path.dirname(original_file)
    for _ in range(level - 1):
        cur_file = os.path.dirname(cur_file)
    cur_name = relative_import_path.lstrip(".")
    for part in cur_name.split("."):
        cur_file = os.path.join(cur_file, part)
    # NOTE: directory import is not handled. Because then it's unclear
    # if such import should produce python module or DictConfig. This can
    # be discussed further if needed.
    if not cur_file.endswith(".py"):
        cur_file += ".py"
    if not PathManager.isfile(cur_file):
        raise ImportError(
            f"Cannot import name {relative_import_path} from "
            f"{original_file}: {cur_file} has to exist."
        )
    return cur_file
